class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        char_substrings = defaultdict(list)

        n = len(s)
        for i in range(n):
            if i > 0 and s[i] == s[i-1]:
                continue
            current_char = s[i]
            length = 1
            char_substrings[current_char].append(length)
            for j in range(i+1, n):
                if s[j] == current_char:
                    length += 1
                    char_substrings[current_char].append(length)
                else:
                    break

        max_len = -1
        for char in char_substrings:
            lengths = char_substrings[char]
            lengths.sort(reverse=True)
            count = 0
            current_max = 0
            for l in lengths:
                if count >= 3:
                    break
                if l == current_max:
                    continue
                current_max = l
                count = lengths.count(l)
            if count >= 3 and current_max > max_len:
                max_len = current_max

        return max_len
